/* Palette: #2d1b3d (dark purple), #f9e2ae (cream), #e8a87c (peach), #7ebc89 (green), #d95d5d (red) */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2d1b3d;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  padding: 16px;
}

.card {
  background: #f9e2ae;
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.6rem;
  color: #2d1b3d;
  margin-bottom: 16px;
  letter-spacing: 1px;
}

/* Pixel pet */
.pet {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.pet-body {
  width: 96px;
  height: 96px;
  background: #7ebc89;
  border-radius: 8px;
  position: relative;
  image-rendering: pixelated;
  box-shadow:
    0 0 0 4px #2d1b3d,
    0 0 0 8px #e8a87c;
}

.pet-eye {
  width: 16px;
  height: 16px;
  background: #2d1b3d;
  position: absolute;
  top: 28px;
  border-radius: 2px;
}

.pet-eye.left { left: 20px; }
.pet-eye.right { right: 20px; }

.pet-mouth {
  width: 32px;
  height: 8px;
  background: #2d1b3d;
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 0 0 8px 8px;
}

/* Mood text */
.mood {
  font-size: 1.1rem;
  font-weight: 600;
  color: #2d1b3d;
  margin-bottom: 20px;
  min-height: 1.6em;
}

/* Bars */
.bars {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.bar-container {
  text-align: left;
}

.bar-container label {
  display: block;
  font-size: 0.95rem;
  font-weight: 600;
  color: #2d1b3d;
  margin-bottom: 4px;
}

.bar {
  height: 20px;
  background: #e8d5b0;
  border-radius: 10px;
  overflow: hidden;
  border: 2px solid #2d1b3d;
}

.bar-fill {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger { background: #d95d5d; }
.bar-fill.happiness { background: #e8a87c; }
.bar-fill.energy { background: #7ebc89; }

/* Buttons */
.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 20px;
  border: 2px solid #2d1b3d;
  border-radius: 12px;
  background: #e8a87c;
  color: #2d1b3d;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 80px;
}

button:hover {
  background: #f0b88e;
}

button:focus-visible {
  outline: 3px solid #2d1b3d;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.95);
  background: #d99a6e;
}

/* Responsive */
@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 1.4rem; }
  button { padding: 10px 14px; font-size: 0.95rem; min-width: 70px; }
  .pet-body { width: 80px; height: 80px; }
  .pet-eye { width: 12px; height: 12px; top: 22px; }
  .pet-eye.left { left: 16px; }
  .pet-eye.right { right: 16px; }
  .pet-mouth { width: 24px; bottom: 18px; }
}

const state = {
  hunger: 80,
  happiness: 70,
  energy: 90
};

const moodEl = document.getElementById('mood');
const bars = {
  hunger: document.getElementById('hunger-bar'),
  happiness: document.getElementById('happiness-bar'),
  energy: document.getElementById('energy-bar')
};

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateMood() {
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood;
  if (avg >= 75) mood = 'Happy';
  else if (avg >= 50) mood = 'Okay';
  else if (avg >= 25) mood = 'Sad';
  else mood = 'Critical';
  moodEl.textContent = 'Mood: ' + mood;
}

function updateBars() {
  for (const key of ['hunger', 'happiness', 'energy']) {
    const bar = bars[key];
    const fill = bar.querySelector('.bar-fill');
    fill.style.width = state[key] + '%';
    bar.setAttribute('aria-valuenow', state[key]);
  }
  updateMood();
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.energy = clamp(state.energy - 5);
  updateBars();
}

function play() {
  state.happiness = clamp(state.happiness + 15);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 5);
  updateBars();
}

function sleep() {
  state.energy = clamp(state.energy + 20);
  state.hunger = clamp(state.hunger - 10);
  updateBars();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

// Passive decay every 10 seconds
setInterval(() => {
  state.hunger = clamp(state.hunger - 2);
  state.happiness = clamp(state.happiness - 1);
  state.energy = clamp(state.energy - 1);
  updateBars();
}, 10000);

updateBars();
